import zlib, struct, sys

def read_png(path):
    d = open(path,'rb').read()
    assert d[:8]==b'\x89PNG\r\n\x1a\n'
    pos=8; idat=b''; pal=None; trns=None
    while pos < len(d):
        ln,typ = struct.unpack('>I4s', d[pos:pos+8]); pos+=8
        data = d[pos:pos+ln]; pos+=ln+4
        if typ==b'IHDR':
            w,h,bd,ct,cm,fm,il = struct.unpack('>IIBBBBB', data)
        elif typ==b'IDAT': idat+=data
        elif typ==b'PLTE': pal=data
        elif typ==b'IEND': break
    raw = zlib.decompress(idat)
    assert bd==8, bd
    nch = {0:1,2:3,3:1,4:2,6:4}[ct]
    stride = w*nch
    out = bytearray(h*stride)
    prev = bytearray(stride)
    p=0
    for y in range(h):
        f = raw[p]; p+=1
        line = bytearray(raw[p:p+stride]); p+=stride
        if f==1:
            for i in range(nch,stride): line[i]=(line[i]+line[i-nch])&255
        elif f==2:
            for i in range(stride): line[i]=(line[i]+prev[i])&255
        elif f==3:
            for i in range(stride):
                a=line[i-nch] if i>=nch else 0
                line[i]=(line[i]+((a+prev[i])>>1))&255
        elif f==4:
            for i in range(stride):
                a=line[i-nch] if i>=nch else 0
                b=prev[i]; c=prev[i-nch] if i>=nch else 0
                pp=a+b-c; pa=abs(pp-a); pb=abs(pp-b); pc=abs(pp-c)
                pr = a if (pa<=pb and pa<=pc) else (b if pb<=pc else c)
                line[i]=(line[i]+pr)&255
        out[y*stride:(y+1)*stride]=line
        prev=line
    return w,h,nch,ct,pal,bytes(out)

def to_rgb(w,h,nch,ct,pal,data):
    px=[]
    for y in range(h):
        row=[]
        for x in range(w):
            i=(y*w+x)*nch
            if ct==3:
                c=data[i]; row.append((pal[3*c],pal[3*c+1],pal[3*c+2]))
            elif ct==0: v=data[i]; row.append((v,v,v))
            elif ct==2: row.append((data[i],data[i+1],data[i+2]))
            elif ct==4: v=data[i]; row.append((v,v,v))
            else: row.append((data[i],data[i+1],data[i+2]))
        px.append(row)
    return px

def write_png(path, px, scale=1):
    h=len(px); w=len(px[0])
    raw=bytearray()
    for y in range(h):
        for _ in range(scale):
            raw.append(0)
            for x in range(w):
                r,g,b=px[y][x]
                for _ in range(scale):
                    raw+=bytes((r,g,b))
    W=w*scale; H=h*scale
    def chunk(t,d):
        c=struct.pack('>I',len(d))+t+d
        return c+struct.pack('>I', zlib.crc32(t+d)&0xffffffff)
    out=b'\x89PNG\r\n\x1a\n'+chunk(b'IHDR',struct.pack('>IIBBBBB',W,H,8,2,0,0,0))+chunk(b'IDAT',zlib.compress(bytes(raw),6))+chunk(b'IEND',b'')
    open(path,'wb').write(out)

if __name__=='__main__':
